    replayBounds:function(points){if(!points.length)return null;var minLat=points[0].lat,maxLat=points[0].lat,minLon=points[0].lon,maxLon=points[0].lon;points.forEach(function(p){minLat=Math.min(minLat,p.lat);maxLat=Math.max(maxLat,p.lat);minLon=Math.min(minLon,p.lon);maxLon=Math.max(maxLon,p.lon);});return{minLat:minLat,maxLat:maxLat,minLon:minLon,maxLon:maxLon};},
    drawReplay:function(exp,state){var c=Q('#replayCanvas'),ctx=c.getContext('2d'),rect=c.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1),w=Math.max(320,Math.floor((rect.width||900)*dpr)),h=Math.max(300,Math.floor((rect.height||480)*dpr));if(c.width!==w||c.height!==h){c.width=w;c.height=h;}ctx.setTransform(dpr,0,0,dpr,0,0);w/=dpr;h/=dpr;ctx.fillStyle='#0b0908';ctx.fillRect(0,0,w,h);var r=state.replay,pts=(r.plannedRoute||[]).concat(r.track||[]).filter(Boolean),bounds=this.replayBounds(pts);if(!bounds){ctx.fillStyle=css('--muted')||'#b8aa91';ctx.font='16px Georgia,serif';ctx.fillText('No recorded route.',24,42);return;}var pad=36,latSpan=Math.max(.0001,bounds.maxLat-bounds.minLat),lonSpan=Math.max(.0001,bounds.maxLon-bounds.minLon);function xy(p){return{x:pad+(p.lon-bounds.minLon)/lonSpan*(w-pad*2),y:h-pad-(p.lat-bounds.minLat)/latSpan*(h-pad*2)};}ctx.strokeStyle='rgba(184,170,145,.35)';ctx.setLineDash([5,6]);ctx.beginPath();(r.plannedRoute||[]).forEach(function(p,i){var q=xy(p);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=css('--focus')||'#f3d77c';ctx.lineWidth=2;ctx.beginPath();(r.track||[]).slice(0,state.index+1).forEach(function(p,i){var q=xy(p);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.stroke();if(state.point){var q=xy(state.point);ctx.fillStyle=css('--bone')||'#efe4cc';ctx.beginPath();ctx.arc(q.x,q.y,6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#090807';ctx.stroke();}},
    renderReplay:function(){var exp=this.selectedExpedition(),ready=!!(exp&&exp.replay),scrub=Q('#replayScrubber');Q('#replayPlayPauseButton').disabled=!ready;scrub.disabled=!ready;Q('#replaySpeedSelect').value=String(S.state.ui.replaySpeed||1);Q('#replayPlayPauseButton').textContent=this.replay.playing?'Pause':'Play';if(!ready){setText('#replayTitle','No completed Expedition selected');setText('#replayClock','00:00');setText('#replayPosition','No track');setText('#replayDistance','0 m');setText('#replayEventCount','0');clear(Q('#replayEventList'));this.drawReplay(null,{replay:{plannedRoute:[],track:[]},index:0,point:null,events:[]});return;}var st=E.replayAt(exp,this.replay.fraction),r=st.replay;scrub.value=Math.round(this.replay.fraction*1000);setText('#replayTitle',exp.title+' · '+exp.status.toUpperCase());var elapsed=st.point&&r.startedAt?Math.max(0,new Date(st.point.at)-new Date(r.startedAt)):0;setText('#replayClock',U.formatDuration(elapsed));setText('#replayPosition',st.point?Number(st.point.lat).toFixed(5)+', '+Number(st.point.lon).toFixed(5)+(st.point.simulated?' · simulated':''):'No recorded fix');var dist=0;for(var i=1;i<=st.index&&i<r.track.length;i+=1){var d=U.distanceM(r.track[i-1],r.track[i]);if(d<500)dist+=d;}setText('#replayDistance',U.formatDistance(dist));setText('#replayEventCount',st.events.length);var box=Q('#replayEventList');clear(box);if(!st.events.length)box.appendChild(U.create('div','empty-state','No events have occurred at this replay position.'));st.events.slice().reverse().slice(0,50).forEach(function(ev){appendLine(box,(ev.kind||'event').toUpperCase(),ev.label||'',U.formatTime(ev.at));});this.drawReplay(exp,st);},
    startReplay:function(){var self=this,exp=this.selectedExpedition();if(!exp||!exp.replay)return;this.stopReplay();this.replay.playing=true;this.replay.lastTick=performance.now();function step(now){if(!self.replay.playing)return;var dt=now-self.replay.lastTick;self.replay.lastTick=now;var duration=Math.max(1000,exp.replay.durationMs||60000),speed=Number(S.state.ui.replaySpeed)||1;self.replay.fraction=U.clamp(self.replay.fraction+dt*speed/duration,0,1);self.renderReplay();if(self.replay.fraction>=1){self.stopReplay();self.renderReplay();return;}self.replay.timer=requestAnimationFrame(step);}this.replay.timer=requestAnimationFrame(step);},
